              </span>
            </div>
            <div class="ml-2">
              <p class="mb-0 text-muted">Dibanding bulan <span
                  class="fs-9 badge badge-outline-primary badge-secondary">{{
                  previousMonthName }}</span></p>
            </div>
          </div>
        </div>
