<script>
import { payloadHelper } from '~/helpers/payload.helper';

export default {
  data() {
    return {
      isLoading: true,
      inflationData: {},
      previousMonthName: ''
    };
  },
  mounted() {
    this.fetchInflationData();
  },
  methods: {
    async fetchInflationData() {
      try {
        // Fetch data from the API
        const param = payloadHelper.normalParam('');
        const response = await this.$inflationMtMRepo.getByParam(param);

        // Check if the response is successful
        if (response.status === 'OK') {
          this.inflationData = response.result[0];
          this.previousMonthName = this.getPreviousMonthName(this.inflationData.kode_bulan);
        } else {
          console.error('Failed to fetch data:', response.message);
        }
      } catch (error) {
        console.error('Error fetching inflation data:', error);
      } finally {
        // Turn off loading state
        this.isLoading = false;
      }
    },
    getPreviousMonthName(currentMonthCode) {
      const months = [
        { kode: '1', nama: 'JAN' },
        { kode: '2', nama: 'FEB' },
        { kode: '3', nama: 'MARET' },
        { kode: '4', nama: 'APRIL' },
        { kode: '5', nama: 'MEI' },
        { kode: '6', nama: 'JUNI' },
        { kode: '7', nama: 'JULI' },
        { kode: '8', nama: 'AGUST' },
        { kode: '9', nama: 'SEPT' },
        { kode: '10', nama: 'OKT' },
        { kode: '11', nama: 'NOV' },
        { kode: '12', nama: 'DES' }
      ];

      // Find the current month
      const currentMonthIndex = months.findIndex((month) => month.kode === currentMonthCode);

      // Calculate the previous month index (wrap around if necessary)
      const previousMonthIndex = currentMonthIndex === 0 ? 11 : currentMonthIndex - 1;

      // Return the previous month's name
      return months[previousMonthIndex].nama;
    },
    getBadgeClass(keterangan) {
      return keterangan === 'Turun' ? 'badge bg-light text-success' : 'badge bg-light text-danger';
    },
    getIconClass(keterangan) {
      return keterangan === 'Turun' ? 'ri-arrow-down-line' : 'ri-arrow-up-line';
    },
    formattedMtMValue() {
      return this.inflationData.tingkat_inflasi
        ? parseFloat(this.inflationData.tingkat_inflasi).toFixed(2).replace('.', ',')
        : '0,00';
    },
  }
};
</script>

